FEEL=["Looks like any other level.","You feel there is something special about this level.","You have a superb feeling about this level.","You have an excellent feeling...","You have a very good feeling...","You have a good feeling...","You feel strangely lucky...","You feel your luck is turning...","You like the look of this place...","This level can't be all bad...","What a boring place..."]

def rx(text):
    t=re.escape(text)
    t=t.replace(re.escape('<mon>'),'(?P<mon>.+?)').replace(re.escape('<item>'),'(?P<item>.+?)')
    t=t.replace(re.escape('<n2>'),r'(?P<n2>\d+)').replace(re.escape('<n>'),r'(?P<n>\d+)')
    t=t.replace(re.escape('<slot>'),r'(?P<slot>[a-z])').replace(re.escape('<act>'),r'(?P<act>.+?)')
    t=t.replace(re.escape('<use>'),r'(?P<use>.+?)').replace(re.escape('<y>'),r'(?P<y>\d+)').replace(re.escape('<x>'),r'(?P<x>\d+)')
    t=t.replace(re.escape('<dir>'),r'(?P<dir>.*?)').replace(re.escape('<sym>'),r'(?P<sym>.)').replace(re.escape('<desc>'),r'(?P<desc>.+)')
    t=t.replace(re.escape('(s)'),r's?').replace(re.escape('a(n)'),'an?')
    return '^'+t+'$'

out=[]
for i in sorted(inp):
    r=inp[i]; text,ev,aud,rel,cond,notes=S[i]
    if text is None: text=r['format']
    if i==12: reg=r'^You have found (?P<n>\d+) gold pieces? worth of (?P<item>.+?)\.$'
    elif i==254: reg=r'^You drop (?P<n>\d+) pieces? of gold\.$'
    elif i==304: reg='^('+'|'.join(re.escape(x) for x in FEEL)+')$'
    elif i==301: reg=r'^Map sector \[(?P<y>\d+),(?P<x>\d+)\], which is(?P<dir>.*?) (?:of )?your sector\.  Direction\?$'
    elif i==232: reg=r'^(?P<act>Took off|Was wielding|Was shooting with|Light source was|Was wearing) (?P<item>.+) \((?P<slot>[a-z])\)\.$'
    elif i==234: reg=r'^(?P<act>Dropped|Was wielding|Was shooting with|Light source was|Was wearing) (?P<item>.+) \((?P<slot>[a-z])\)\.$'
    elif i==242: reg=r'^(?P<act>You are wielding|You are shooting with|Your light source is|You are wearing) (?P<item>.+) \((?P<slot>[a-z])\)\.$'
    elif i==273: reg=r'^$'
    elif i==216: reg=r'^(?P<mon>.+?) throws you an? (?P<item>.+?)!$'
    elif i==218: reg=r'^(?P<mon>.+?) hits you with an? (?P<item>.+?)!$'
    else: reg=rx(text)
    re.compile(reg)
    out.append([i,r['file'],r['line'],text,ev,aud,rel,reg,cond,notes])
    if i==304:
        for k,f in enumerate(FEEL):
            out.append([i,r['file'],r['line'],f,'level.feeling.%d'%k,'self','medium',rx(f),'do_cmd_feeling(): feeling index %d (cmd4.c:%d-%d)'%(k,165+k,165+k),'Variant of row 304.' if k else 'Variant of row 304. Index 0 also when no time has passed.'])
w=csv.writer(open(D+'M4_catalogue.csv','w',newline=''))
w.writerow('id,file,line,text,event,audience,pilot_relevance,regex,condition,notes'.split(','))
w.writerows(out)
